mapper.select:
SELECT rm.*, CASE rm.handle_method WHEN 1 THEN rm.freight ELSE rm.total_amount END AS totalAmount, rm.warehouse_id AS 'warehouse.id', wh.name AS 'warehouse.name', bc.name AS branch_company_name, su.NAME AS create_user_name, su2.NAME AS audit_user_name, cp.NAME AS project_name, cp.serial_number AS project_code FROM project_return_product_main AS rm LEFT JOIN contract_project cp ON cp.id = project_id LEFT JOIN sys_user su ON su.id = rm.create_user_id LEFT JOIN sys_user su2 ON su2.id = rm.audit_user_id LEFT JOIN sys_branch_company AS bc ON bc.id = rm.branch_company_id LEFT JOIN mes_building_warehouse AS wh on rm.warehouse_id = wh.id WHERE rm.bool_delete_enum = 0
and rm.project_id = #{projectId}
AND (cp.name like concat('%', #{projectName}, '%') or cp.short_name like concat('%',#{projectName},'%'))
and su.name like concat('%', #{createUserName}, '%'))
and su2.name like concat('%', #{auditUserName},'%'))
and rm.serial_number LIKE concat('%', #{serialNumber}, '%')
and rm.audit_status = #{auditStatus}
and rm.product_type = #{productType}
and rm.relation_type = #{relationType}
and DATE(rm.create_time) >= DATE(#{createTimeStartDate})
and DATE(rm.create_time) <= DATE(#{createTimeEndDate})
ORDER BY rm.audit_status, rm.id DESC
